// ============================================================================
// 1. COORDENADAS DAS ZONAS E SNAP POINTS (SUPORTE ATÉ 10 JOGADORES)
// ============================================================================

type Vetor3 = [number, number, number];
type FaseJogo = "FASE_1" | "FASE_2" | "FASE_3" | "FASE_4" | "FASE_5" | "FIM_DE_JOGO";

interface SlotAtaque {
  indice: number; // 1 a 10
  nomeSnap: string; // "Ataque_1" a "Ataque_10"
  ponto: Vetor3;
  vinculado: boolean;
}

interface SlotOcorrenciaMesa {
  indice: number; // 1 a 3
  nomeSnap: string; // "Ocorrencia_1" a "Ocorrencia_3"
  ponto: Vetor3;
  vinculado: boolean;
  nomeDepositoA: string; // "Deposito_1A" a "Deposito_3A"
  pontoDepositoA: Vetor3;
  vinculadoDepositoA: boolean;
  nomeDepositoB: string; // "Deposito_1B" a "Deposito_3B"
  pontoDepositoB: Vetor3;
  vinculadoDepositoB: boolean;
}

interface PareamentoOcorrenciaDepositos {
  indice: number;
  nomeOcorrencia: string;
  cartaOcorrencia: any;
  cartasDepositoA: any[];
  cartasDepositoB: any[];
  todasCartasAcao: any[];
}

interface ResultadoPontuacao {
  pontos: number;
  percentual: number;
  passosDebug: string[];
}

const MAX_JOGADORES = 10;
const TOTAL_SLOTS_OCORRENCIA_MESA = 3;
const ALTURA_MESA = 1.515;
const RAIO_DETECCAO = 0.14;
const NOME_BOTAO_MESA = "Botao_Avancar";
const HUD_BOTAO_ID = "btn_avancar_fase";

// Coordenadas de reserva (substituídas automaticamente pelas posições reais dos Snap Points da cena)
const POSICOES_BASE: Record<string, Vetor3> = {
  Acao_1: [-0.45, 1.52, 0.22],
  Acao_2: [-0.15, 1.52, 0.22],
  Acao_3: [0.15, 1.52, 0.22],
  Acao_4: [0.45, 1.52, 0.22],
  Acao_5: [-0.3, 1.52, -0.12],
  Acao_6: [0.0, 1.52, -0.12],
  Acao_7: [0.3, 1.52, -0.12],
  Zona_Descarte: [0.949, 1.536, 0.093],
  OcorrenciasResolvidas: [0.95, 1.536, -0.25],
  OcorrenciasFail: [0.95, 1.536, 0.42],
};

const POSICOES_MESA: Record<string, Vetor3> = { ...POSICOES_BASE };

const ORDEM_CORES_ASSENTO: Record<string, number> = {
  red: 1,
  blue: 2,
  green: 3,
  yellow: 4,
  purple: 5,
  orange: 6,
  teal: 7,
  cyan: 7,
  pink: 8,
  white: 9,
  black: 10,
};

// 1. Snap Points individuais de cada jogador na Fase 3 (Ataque_1 a Ataque_10)
const SLOTS_ATAQUE: SlotAtaque[] = Array.from({ length: MAX_JOGADORES }, (_, idx) => {
  const num = idx + 1;
  return {
    indice: num,
    nomeSnap: `Ataque_${num}`,
    ponto: [0, ALTURA_MESA, 0],
    vinculado: false,
  };
});

// 2. Snap Points centrais da Fase 4/5 (Ocorrencia_1..3 pareados com Deposito_1A/1B .. 3A/3B)
const SLOTS_OCORRENCIA_MESA: SlotOcorrenciaMesa[] = Array.from(
  { length: TOTAL_SLOTS_OCORRENCIA_MESA },
  (_, idx) => {
    const num = idx + 1;
    return {
      indice: num,
      nomeSnap: `Ocorrencia_${num}`,
      ponto: [0, ALTURA_MESA, 0],
      vinculado: false,
      nomeDepositoA: `Deposito_${num}A`,
      pontoDepositoA: [0, ALTURA_MESA, 0],
      vinculadoDepositoA: false,
      nomeDepositoB: `Deposito_${num}B`,
      pontoDepositoB: [0, ALTURA_MESA, 0],
      vinculadoDepositoB: false,
    };
  }
);

// ============================================================================
// 2. ESTADO DO JOGO
// ============================================================================

interface EstadoJogo {
  jogoIniciado: boolean;
  rodada: number;
  faseAtual: FaseJogo;
  pontuacaoOculta: number;
  pontuacaoFracasso: number;
  cartasAcaoNaMesa: Set<string>;
  cartasOcorrenciaEmDisputa: Set<string>;
  pareamentosRodada: PareamentoOcorrenciaDepositos[];
  idsModeloOcorrencia: Set<string>;
  idsModeloAcao: Set<string>;
  assentosInicializados: Set<string>;
  mapaAssentoParaIndice: Map<string, number>;
  snapsAcaoVinculados: number;
  snapsAtaqueVinculados: number;
  snapsOcorrenciaVinculados: number;
  snapsDepositoVinculados: number;
  deckOcorrenciaFaceUpBase: boolean;
  deckAcaoFaceUpBase: boolean;
  ultimoStatusFase3: string;
  posicoesAnteriores: Map<string, Vetor3>;
  eventosRegistrados: boolean;
  ocupado: boolean;
}

const estado: EstadoJogo = {
  jogoIniciado: false,
  rodada: 1,
  faseAtual: "FASE_1",
  pontuacaoOculta: 0,
  pontuacaoFracasso: 0,
  cartasAcaoNaMesa: new Set<string>(),
  cartasOcorrenciaEmDisputa: new Set<string>(),
  pareamentosRodada: [],
  idsModeloOcorrencia: new Set<string>(),
  idsModeloAcao: new Set<string>(),
  assentosInicializados: new Set<string>(),
  mapaAssentoParaIndice: new Map<string, number>(),
  snapsAcaoVinculados: 0,
  snapsAtaqueVinculados: 0,
  snapsOcorrenciaVinculados: 0,
  snapsDepositoVinculados: 0,
  deckOcorrenciaFaceUpBase: false,
  deckAcaoFaceUpBase: false,
  ultimoStatusFase3: "",
  posicoesAnteriores: new Map<string, Vetor3>(),
  eventosRegistrados: false,
  ocupado: false,
};

// ============================================================================
// 3. FUNÇÕES UTILITÁRIAS E DESCOBERTA DE ASSENTOS / SNAP POINTS
// ============================================================================

function lerVetor(pos: any, yFallback = ALTURA_MESA): Vetor3 {
  if (Array.isArray(pos)) return [Number(pos[0] ?? 0), Number(pos[1] ?? yFallback), Number(pos[2] ?? 0)];
  if (pos && typeof pos === "object") return [Number(pos.x ?? 0), Number(pos.y ?? yFallback), Number(pos.z ?? 0)];
  return [0, yFallback, 0];
}

function normalizarNomeSnap(texto: string): string {
  return String(texto ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[\s-]+/g, "_")
    .replace(/_0+(\d+[a-z]?)$/, "_$1");
}

function obterNomesCandidatosSnap(sp: any): string[] {
  if (!sp || typeof sp !== "object") return [];
  const candidatos = [sp.name, sp.label, sp.displayName, sp.title, sp.id];
  const normalizados: string[] = [];
  for (const c of candidatos) {
    if (typeof c === "string" && c.trim().length > 0) {
      normalizados.push(normalizarNomeSnap(c));
    }
  }
  return normalizados;
}

async function pausaFisica(segundos = 0.06): Promise<boolean> {
  const w = world as any;
  if (typeof w.wait === "function") {
    await w.wait(segundos);
    return true;
  }
  const timer = (globalThis as any).setTimeout;
  if (typeof timer === "function") {
    await new Promise<void>((resolve) => timer(resolve, Math.max(15, Math.round(segundos * 1000))));
    return true;
  }
  return false;
}

function extrairIndiceAssento(seatId: string, label = "", fallback = 1): number {
  const idNorm = String(seatId ?? "").trim().toLowerCase();
  if (ORDEM_CORES_ASSENTO[idNorm] !== undefined) {
    return ORDEM_CORES_ASSENTO[idNorm];
  }

  const matchLabel = String(label ?? "").match(/(\d+)/);
  if (matchLabel) {
    const num = Number(matchLabel[1]);
    if (num >= 1 && num <= MAX_JOGADORES) return num;
  }

  const matchId = idNorm.match(/(\d+)/);
  if (matchId) {
    const num = Number(matchId[1]);
    if (num === 0) return 1;
    if (num >= 1 && num <= MAX_JOGADORES) return num;
  }

  return Math.max(1, Math.min(MAX_JOGADORES, fallback));
}

function normalizarColecao(raw: any): any[] {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  if (typeof raw === "object") {
    if (Array.isArray(raw.players)) return raw.players;
    if (Array.isArray(raw.zones)) return raw.zones;
    const lista: any[] = [];
    for (const [chave, valor] of Object.entries(raw)) {
      if (Array.isArray(valor)) {
        for (const item of valor) {
          if (item && typeof item === "object") lista.push({ __chaveSeat: chave, ...item });
        }
      } else if (valor && typeof valor === "object") {
        lista.push({ __chaveSeat: chave, ...(valor as Record<string, any>) });
      }
    }
    return lista;
  }
  return [];
}

async function mapearAssentosDaCena() {
  const w = world as any;
  const seatZonesBruto = typeof w.getSeatZones === "function" ? await w.getSeatZones() : [];
  const listaZonas = normalizarColecao(seatZonesBruto);

  const mapa = new Map<string, number>();
  let contadorFallback = 1;

  for (const z of listaZonas) {
    if (!z || typeof z !== "object") continue;
    const seatId = String(z.seat ?? z.seatId ?? z.__chaveSeat ?? "").trim().toLowerCase();
    if (!seatId || mapa.has(seatId)) continue;

    const nomeAssento = String(z.name ?? z.label ?? "");
    const indice = extrairIndiceAssento(seatId, nomeAssento, contadorFallback++);
    mapa.set(seatId, indice);
  }

  estado.mapaAssentoParaIndice = mapa;
}

function encontrarSnapPorNome(snapPoints: any[], usados: Set<any>, nomeAlvo: string): any | null {
  const alvoNorm = normalizarNomeSnap(nomeAlvo);
  const alvoCompacto = alvoNorm.replace(/_/g, "");

  return (
    snapPoints.find((sp: any) => {
      if (usados.has(sp)) return false;
      const nomesSp = obterNomesCandidatosSnap(sp);
      return nomesSp.some((n) => n === alvoNorm || n.replace(/_/g, "") === alvoCompacto);
    }) ?? null
  );
}

function encontrarSnapPorProximidade(
  snapPoints: any[],
  usados: Set<any>,
  coordenadaBase: Vetor3,
  raioMax = 0.25
): any | null {
  let maisProximo: any = null;
  let menorDist = raioMax;
  for (const sp of snapPoints) {
    if (usados.has(sp)) continue;
    const [sx, , sz] = lerVetor(sp.position ?? sp);
    const dist = Math.hypot(sx - coordenadaBase[0], sz - coordenadaBase[2]);
    if (dist < menorDist) {
      menorDist = dist;
      maisProximo = sp;
    }
  }
  return maisProximo;
}

async function sincronizarComSnapPoints() {
  await mapearAssentosDaCena();

  const snapPoints: any[] = (await world.getSnapPoints?.()) ?? [];
  const usados = new Set<any>();
  let acoesVinculadas = 0;

  // 1. Vincula Acao_1..7, Zona_Descarte, OcorrenciasResolvidas e OcorrenciasFail
  const chavesMesa = Object.keys(POSICOES_BASE);
  const naoVinculadosMesa: string[] = [];

  for (const chave of chavesMesa) {
    const sp = encontrarSnapPorNome(snapPoints, usados, chave);
    if (sp) {
      usados.add(sp);
      POSICOES_MESA[chave] = lerVetor(sp.position ?? sp);
      if (chave.startsWith("Acao_")) acoesVinculadas++;
    } else {
      naoVinculadosMesa.push(chave);
    }
  }

  // 2. Vincula Ataque_1..10 (pontos dos jogadores na Fase 3)
  let ataquesVinculados = 0;
  for (const slot of SLOTS_ATAQUE) {
    const spAtaque = encontrarSnapPorNome(snapPoints, usados, slot.nomeSnap);
    if (spAtaque) {
      usados.add(spAtaque);
      slot.ponto = lerVetor(spAtaque.position ?? spAtaque);
      slot.vinculado = true;
      ataquesVinculados++;
    } else {
      slot.vinculado = false;
    }
  }

  // 3. Vincula Ocorrencia_1..3 e Deposito_1A/1B .. 3A/3B (pontos distintos da Fase 4/5)
  let ocorrenciasVinculados = 0;
  let depositosVinculados = 0;

  for (const slotOc of SLOTS_OCORRENCIA_MESA) {
    const spOcorrencia = encontrarSnapPorNome(snapPoints, usados, slotOc.nomeSnap);
    if (spOcorrencia) {
      usados.add(spOcorrencia);
      slotOc.ponto = lerVetor(spOcorrencia.position ?? spOcorrencia);
      slotOc.vinculado = true;
      ocorrenciasVinculados++;
    } else {
      slotOc.vinculado = false;
    }

    const spDepA = encontrarSnapPorNome(snapPoints, usados, slotOc.nomeDepositoA);
    if (spDepA) {
      usados.add(spDepA);
      slotOc.pontoDepositoA = lerVetor(spDepA.position ?? spDepA);
      slotOc.vinculadoDepositoA = true;
      depositosVinculados++;
    } else {
      slotOc.vinculadoDepositoA = false;
    }

    const spDepB = encontrarSnapPorNome(snapPoints, usados, slotOc.nomeDepositoB);
    if (spDepB) {
      usados.add(spDepB);
      slotOc.pontoDepositoB = lerVetor(spDepB.position ?? spDepB);
      slotOc.vinculadoDepositoB = true;
      depositosVinculados++;
    } else {
      slotOc.vinculadoDepositoB = false;
    }
  }

  for (const chave of naoVinculadosMesa) {
    const sp = encontrarSnapPorProximidade(snapPoints, usados, POSICOES_BASE[chave], 0.25);
    if (sp) {
      usados.add(sp);
      POSICOES_MESA[chave] = lerVetor(sp.position ?? sp);
      if (chave.startsWith("Acao_")) acoesVinculadas++;
    }
  }

  estado.snapsAcaoVinculados = acoesVinculadas;
  estado.snapsAtaqueVinculados = ataquesVinculados;
  estado.snapsOcorrenciaVinculados = ocorrenciasVinculados;
  estado.snapsDepositoVinculados = depositosVinculados;
}

function registrarModelosDoDeck(deck: any, destinoSet: Set<string>) {
  if (!deck) return;
  const meta = deck.metadata ?? deck.data?.metadata;
  const cards = meta?.customDeck?.cards;
  if (Array.isArray(cards)) {
    for (const c of cards) {
      if (c?.cardId) destinoSet.add(String(c.cardId));
      if (c?.label) destinoSet.add(String(c.label));
    }
  }
}

function ehCartaDeOcorrencia(carta: any): boolean {
  if (!carta) return false;
  const idEntidade = String(carta.id ?? "");
  if (idEntidade && estado.cartasAcaoNaMesa.has(idEntidade)) {
    return false;
  }

  const meta = carta.metadata ?? carta.data?.metadata;
  const cardId = String(meta?.cardId ?? carta.cardid ?? carta.name ?? "");
  if (
    cardId &&
    estado.idsModeloAcao.size > 0 &&
    estado.idsModeloOcorrencia.size > 0 &&
    estado.idsModeloAcao.has(cardId) &&
    !estado.idsModeloOcorrencia.has(cardId)
  ) {
    return false;
  }

  return true;
}

async function listarTodosObjetos(): Promise<any[]> {
  const objetos: any[] = await world.getAllObjects();
  return objetos ?? [];
}

async function obterObjetoPorNome(nome: string): Promise<any> {
  const todos = await listarTodosObjetos();
  return todos.find((obj: any) => obj?.name === nome) ?? null;
}

function dentroDaArea(posObj: any, centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO): boolean {
  const [ox, , oz] = lerVetor(posObj);
  const [cx, , cz] = centro;
  return Math.abs(ox - cx) <= raioX && Math.abs(oz - cz) <= raioZ;
}

function estaEmAlgumSnapPointDaMesa(posObj: any): boolean {
  for (const centro of Object.values(POSICOES_MESA)) {
    if (dentroDaArea(posObj, centro, RAIO_DETECCAO, RAIO_DETECCAO)) {
      return true;
    }
  }
  for (const slot of SLOTS_ATAQUE) {
    if (slot.vinculado && dentroDaArea(posObj, slot.ponto, RAIO_DETECCAO, RAIO_DETECCAO)) return true;
  }
  for (const slotOc of SLOTS_OCORRENCIA_MESA) {
    if (slotOc.vinculado && dentroDaArea(posObj, slotOc.ponto, RAIO_DETECCAO, RAIO_DETECCAO)) return true;
    if (slotOc.vinculadoDepositoA && dentroDaArea(posObj, slotOc.pontoDepositoA, RAIO_DETECCAO, RAIO_DETECCAO)) return true;
    if (slotOc.vinculadoDepositoB && dentroDaArea(posObj, slotOc.pontoDepositoB, RAIO_DETECCAO, RAIO_DETECCAO)) return true;
  }
  return false;
}

function estaEmAlgumPontoAtaque(posObj: any): boolean {
  for (const slot of SLOTS_ATAQUE) {
    if (slot.vinculado && dentroDaArea(posObj, slot.ponto, RAIO_DETECCAO, RAIO_DETECCAO)) {
      return true;
    }
  }
  return false;
}

function estaCartaAssentada(obj: any, centro: Vetor3): boolean {
  if (!obj || obj.isHeld || obj.heldBy || obj.grabbedBy || obj.isDragging) return false;
  const [ox, oy, oz] = lerVetor(obj.position);
  if (oy > Math.max(centro[1], ALTURA_MESA) + 0.08) return false;
  const chaveId = String(obj.id ?? "");
  if (chaveId) {
    const posAnt = estado.posicoesAnteriores.get(chaveId);
    if (!posAnt || Math.hypot(ox - posAnt[0], oy - posAnt[1], oz - posAnt[2]) > 0.008) return false;
  }
  return true;
}

function atualizarHistoricoPosicoes(objetos: any[]) {
  const proximoMapa = new Map<string, Vetor3>();
  for (const obj of objetos) {
    if (obj?.id) proximoMapa.set(String(obj.id), lerVetor(obj.position));
  }
  estado.posicoesAnteriores = proximoMapa;
}

async function objetosNaArea(centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false): Promise<any[]> {
  const todos = await listarTodosObjetos();
  return todos.filter((obj: any) => {
    if (!obj || obj.name === "Deck_Ocorrencia" || obj.name === "Deck_Acao") return false;
    const kind = String(obj.kind ?? "").toLowerCase();
    if (kind !== "card" && kind !== "deck") return false;
    return dentroDaArea(obj.position, centro, raioX, raioZ) && (!apenasAssentadas || estaCartaAssentada(obj, centro));
  });
}

async function cartasNaArea(centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false): Promise<any[]> {
  const objetos = await objetosNaArea(centro, raioX, raioZ, apenasAssentadas);
  return objetos.filter((obj: any) => (obj.stackCount ?? 1) <= 1);
}

function contarTotalCartas(objetos: any[]): number {
  return objetos.reduce((soma, obj) => soma + Number(obj?.stackCount ?? 1), 0);
}

async function definirTravaFisica(obj: any, travar: boolean) {
  if (!obj) return;
  try {
    if (travar && typeof obj.lock === "function") await obj.lock();
    else if (!travar && typeof obj.unlock === "function") await obj.unlock();
    else if ("locked" in obj) obj.locked = travar;
  } catch (_) {}
}

async function moverCartaParaPonto(
  carta: any,
  destino: Vetor3,
  viradaParaCima: boolean,
  rotacaoY = 0,
  indicePilha = 0,
  travarNaMesa = false
) {
  if (!carta || !destino) return;
  await definirTravaFisica(carta, false);

  if (viradaParaCima && carta.faceUp === false && typeof carta.flip === "function") {
    await carta.flip();
    await pausaFisica(0.22);
  } else if (!viradaParaCima && carta.faceUp === true && typeof carta.flip === "function") {
    await carta.flip();
    await pausaFisica(0.22);
  }

  if (typeof carta.setRotation === "function") {
    const rotAtual = Array.isArray(carta.rotation) ? carta.rotation : [0, rotacaoY, 0];
    const virouPeloEixoX = Math.abs(Number(rotAtual[0] ?? 0)) > 90;
    const rzNormalizado = virouPeloEixoX ? (Math.abs(Number(rotAtual[2] ?? 0)) > 90 ? 0 : 180) : Number(rotAtual[2] ?? 0);
    await carta.setRotation([0, rotacaoY, rzNormalizado]);
  }

  const ySeguro = Number((Math.max(destino[1], ALTURA_MESA) + indicePilha * 0.015).toFixed(3));
  if (typeof carta.setPosition === "function") await carta.setPosition([destino[0], ySeguro, destino[2]]);

  await definirTravaFisica(carta, travarNaMesa);
  if (typeof carta.refresh === "function") await carta.refresh();
  await pausaFisica(0.06);
}

async function puxarCartaDoDeck(deck: any): Promise<any | null> {
  if (!deck || (deck.stackCount ?? 0) <= 0) return null;
  let carta = typeof deck.drawCard === "function" ? await deck.drawCard() : typeof deck.draw === "function" ? await deck.draw(1) : null;
  if (Array.isArray(carta)) carta = carta[0];
  return carta ?? null;
}

async function descompactarPilhas(objetos: any[]): Promise<any[]> {
  const individuais: any[] = [];
  for (const obj of objetos) {
    if (!obj) continue;
    await definirTravaFisica(obj, false);
    while ((obj.stackCount ?? 1) > 1) {
      const extra = await puxarCartaDoDeck(obj);
      if (!extra) break;
      individuais.push(extra);
    }
    individuais.push(obj);
  }
  return individuais;
}

function extrairIdentificadorPlayer(p: any, fallbackIdx: number): string {
  if (!p || typeof p !== "object") return "";
  if (p.isSpectator === true) return "";

  const papel = String(p.role ?? p.type ?? "").trim().toLowerCase();
  if (papel === "spectator") return "";

  const candidatos = [
    p.seat,
    p.seatId,
    p.seatColor,
    p.color,
    p.handSeat,
    p.seatName,
    p.assignedSeat,
    typeof p.seatIndex === "number" ? `seat_${p.seatIndex + 1}` : "",
  ];

  for (const c of candidatos) {
    const val = String(c ?? "").trim().toLowerCase();
    if (!val || val === "null" || val === "undefined") continue;
    if (val === "spectator" || val === "none") return "";
    return val;
  }

  const idJogador = String(p.id ?? p.playerId ?? p.userId ?? p.__chaveSeat ?? "").trim().toLowerCase();
  return idJogador || `player_${fallbackIdx + 1}`;
}

async function obterAssentosOcupados(): Promise<string[]> {
  const w = world as any;
  const playersBruto = typeof w.getPlayers === "function" ? await w.getPlayers() : [];
  const listaPlayers = normalizarColecao(playersBruto);

  const assentos: string[] = [];

  for (let i = 0; i < listaPlayers.length; i++) {
    const idAssento = extrairIdentificadorPlayer(listaPlayers[i], i);
    if (idAssento && !assentos.includes(idAssento)) {
      assentos.push(idAssento);
    }
  }

  const seatZonesBruto = typeof w.getSeatZones === "function" ? await w.getSeatZones() : [];
  const listaZonas = normalizarColecao(seatZonesBruto);
  for (const z of listaZonas) {
    if (!z || typeof z !== "object") continue;
    const ocupado = Boolean(z.occupied || z.playerId || z.occupiedBy || z.occupantId || z.player);
    if (!ocupado) continue;
    const seat = String(z.seat ?? z.seatId ?? z.__chaveSeat ?? "").trim().toLowerCase();
    if (seat && seat !== "spectator" && seat !== "none" && !assentos.includes(seat)) {
      assentos.push(seat);
    }
  }

  return assentos.slice(0, MAX_JOGADORES);
}

async function obterSlotsAtaqueAtivos(): Promise<SlotAtaque[]> {
  const assentosAtuais = await obterAssentosOcupados();
  const todosAssentosDaRodada: string[] = [...assentosAtuais];

  for (const seat of estado.assentosInicializados) {
    if (!todosAssentosDaRodada.includes(seat)) {
      todosAssentosDaRodada.push(seat);
    }
  }

  const indicesUsados = new Set<number>();
  const slotsAtivos: SlotAtaque[] = [];

  for (let i = 0; i < todosAssentosDaRodada.length; i++) {
    const seat = todosAssentosDaRodada[i];
    let indice = estado.mapaAssentoParaIndice.get(seat) ?? extrairIndiceAssento(seat, "", i + 1);

    if (indicesUsados.has(indice)) {
      const livre = SLOTS_ATAQUE.find((s) => !indicesUsados.has(s.indice));
      if (livre) indice = livre.indice;
    }

    indicesUsados.add(indice);
    const slot = SLOTS_ATAQUE[indice - 1];
    if (slot) slotsAtivos.push(slot);
  }

  return slotsAtivos.sort((a, b) => a.indice - b.indice);
}

async function virarParaCimaCartasNasMaos() {
  const todos = await listarTodosObjetos();
  for (const obj of todos) {
    if (!obj || obj.name === "Deck_Ocorrencia" || obj.name === "Deck_Acao") continue;
    const kind = String(obj.kind ?? "").toLowerCase();
    if (kind !== "card") continue;
    if (estaEmAlgumSnapPointDaMesa(obj.position)) continue;

    if (obj.faceUp === false && typeof obj.flip === "function") {
      try {
        await obj.flip();
        if (typeof obj.refresh === "function") await obj.refresh();
        await pausaFisica(0.05);
      } catch (_) {}
    }
  }
}

async function contarCartasNasMaos(): Promise<number> {
  const todos = await listarTodosObjetos();
  let total = 0;
  for (const obj of todos) {
    if (!obj || obj.name === "Deck_Ocorrencia" || obj.name === "Deck_Acao") continue;
    const kind = String(obj.kind ?? "").toLowerCase();
    if (kind !== "card" && kind !== "deck") continue;
    if (estaEmAlgumSnapPointDaMesa(obj.position)) continue;
    total += Number(obj.stackCount ?? 1);
  }
  return total;
}

async function distribuirCartasParaAssentosOcupados(deck: any, quantidadePorJogador: number) {
  if (!deck || typeof deck.deal !== "function") return;

  for (let i = 0; i < quantidadePorJogador; i++) {
    if ((deck.stackCount ?? 0) <= 0) break;
    try {
      await deck.deal();
      if (typeof deck.refresh === "function") {
        await deck.refresh();
      }
      await pausaFisica(0.28);
    } catch (_) {}
  }

  await virarParaCimaCartasNasMaos();
}

