function atualizarBotaoHud(visivel: boolean, rotulo = "Avançar Fase") {
  try {
    if (typeof ui === "undefined") return;
    const hud = ui as any;
    if (visivel && typeof hud.show === "function") {
      hud.show({
        id: HUD_BOTAO_ID,
        kind: "actionStrip",
        region: "bottomRight",
        actions: [{ id: "avancar_fase", label: rotulo, tone: "primary" }],
      });
    } else if (!visivel && typeof hud.hide === "function") {
      hud.hide(HUD_BOTAO_ID);
    }
  } catch (_) {}
}

async function acionarAvancoManualDeFase() {
  if (estado.ocupado) return;
  estado.ocupado = true;
  try {
    if (estado.faseAtual === "FASE_3") {
      await validarEAvancarParaFase4();
    } else if (estado.faseAtual === "FASE_4") {
      await validarEAvancarParaFase5();
    }
  } finally {
    estado.ocupado = false;
  }
}

async function registrarInteracoesDeAvanco() {
  if (estado.eventosRegistrados) return;
  estado.eventosRegistrados = true;

  const w = world as any;

  // 1. Clique simples na mesa:
  //    - No objeto "Botao_Avancar" (se existir na cena)
  //    - No "Deck_Acao" (funciona na Fase 3 e na Fase 4)
  //    - Em qualquer carta posicionada em Ataque_1..10 durante a Fase 3
  try {
    if (typeof globalEvents !== "undefined") {
      const ge = globalEvents as any;
      if (ge?.onObjectClicked?.add) {
        ge.onObjectClicked.add((obj: any) => {
          const nome = String(obj?.name ?? "").trim();

          if (nome === NOME_BOTAO_MESA || nome === "Deck_Acao" || nome === "Deck_Ocorrencia") {
            acionarAvancoManualDeFase();
            return;
          }

          if (estado.faseAtual === "FASE_3" && obj?.position && estaEmAlgumPontoAtaque(obj.position)) {
            acionarAvancoManualDeFase();
          }
        });
      }
    }
  } catch (_) {}

  // 2. Clique no botão da HUD (Game UI)
  try {
    if (typeof ui !== "undefined") {
      const hud = ui as any;
      if (hud?.onAction?.add) {
        hud.onAction.add((ev: any) => {
          if (ev?.actionId === "avancar_fase" || ev?.widgetId === HUD_BOTAO_ID) {
            acionarAvancoManualDeFase();
          }
        });
      }
    }
  } catch (_) {}

  // 3. Opção "Avançar Fase" no menu de botão direito do Deck_Acao, Deck_Ocorrencia e Botao_Avancar
  if (typeof w.addObjectMenuItem === "function") {
    const alvos = [NOME_BOTAO_MESA, "Deck_Acao", "Deck_Ocorrencia"];
    for (const nomeAlvo of alvos) {
      const ent = await obterObjetoPorNome(nomeAlvo);
      if (ent?.id) {
        try {
          w.addObjectMenuItem(ent.id, "Avançar Fase", () => {
            acionarAvancoManualDeFase();
          });
        } catch (_) {}
      }
    }
  }
}

