async function iniciarJogo() {
  if (estado.jogoIniciado) return;
  estado.jogoIniciado = true;
  estado.rodada = 1;
  estado.pontuacaoOculta = 0;
  estado.pontuacaoFracasso = 0;
  estado.assentosInicializados.clear();
  estado.cartasAcaoNaMesa.clear();

  await sincronizarComSnapPoints();
  await registrarInteracoesDeAvanco();

  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
  const deckAcao = await obterObjetoPorNome("Deck_Acao");

  registrarModelosDoDeck(deckOcorrencia, estado.idsModeloOcorrencia);
  registrarModelosDoDeck(deckAcao, estado.idsModeloAcao);

  if (typeof deckOcorrencia?.shuffle === "function") await deckOcorrencia.shuffle();
  if (typeof deckAcao?.shuffle === "function") await deckAcao.shuffle();
  if (deckOcorrencia) estado.deckOcorrenciaFaceUpBase = Boolean(deckOcorrencia.faceUp);
  if (deckAcao) estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);

  await executarFase1();
  iniciarMonitoramentoContinuo();
}

// FASE 1: Distribuir 5 cartas de Ocorrência na Rodada 1 (ou 1 carta nas rodadas seguintes) na mão de cada jogador
async function executarFase1() {
  estado.faseAtual = "FASE_1";
  atualizarBotaoHud(false);
  estado.assentosInicializados.clear();

  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
  const assentosAtivos = await obterAssentosOcupados();

  const quantidadeParaComprar = estado.rodada === 1 ? 5 : 1;
  await distribuirCartasParaAssentosOcupados(deckOcorrencia, quantidadeParaComprar);

  for (const seat of assentosAtivos) {
    estado.assentosInicializados.add(seat);
  }

  await executarFase2();
}

// FASE 2: Distribuir 7 cartas de Ação nos Snap Points Acao_1 a Acao_7 da mesa
async function executarFase2() {
  estado.faseAtual = "FASE_2";
  const deckAcao = await obterObjetoPorNome("Deck_Acao");
  estado.cartasAcaoNaMesa.clear();

  for (let passada = 0; passada < 2; passada++) {
    for (let i = 1; i <= 7; i++) {
      const pontoAcao = POSICOES_MESA[`Acao_${i}`];
      const cartasAtuais = await objetosNaArea(pontoAcao, RAIO_DETECCAO, RAIO_DETECCAO, false);

      if (cartasAtuais.length === 0) {
        const novaCarta = await puxarCartaDoDeck(deckAcao);
        if (novaCarta) {
          await pausaFisica(0.08);
          await moverCartaParaPonto(novaCarta, pontoAcao, true, 0, 0, false);
          if (novaCarta.id) {
            estado.cartasAcaoNaMesa.add(String(novaCarta.id));
          }
        }
      } else {
        for (const c of cartasAtuais) {
          if (c?.id) estado.cartasAcaoNaMesa.add(String(c.id));
        }
      }
    }
  }

  await iniciarFase3();
}

// FASE 3: Cada jogador ativo coloca 1 carta de Ocorrência no seu Snap Point de Ataque (Ataque_1..N)
async function iniciarFase3() {
  estado.faseAtual = "FASE_3";
  estado.cartasOcorrenciaEmDisputa.clear();
  estado.ultimoStatusFase3 = "";
  atualizarBotaoHud(true, "Revelar Ocorrências (Fase 4)");

  const slotsAtivos = await obterSlotsAtaqueAtivos();
  const nomesAtivos = slotsAtivos.map((s) => s.nomeSnap).join(", ");

  world.broadcast(
    `Rodada ${estado.rodada} — Fase 3 (${slotsAtivos.length} jogador(es): ${
      nomesAtivos || "aguardando assentos"
    }): Coloque 1 carta de Ocorrência da mão em cada Snap Point de Ataque ativo. Quando estiver pronto, clique no Deck_Acao (ou em uma carta de Ataque) para revelar.`
  );
}

async function verificarNovosAssentosOcupados() {
  if (estado.faseAtual !== "FASE_3") return;
  const assentosAtivos = await obterAssentosOcupados();
  const novos = assentosAtivos.filter((seat) => !estado.assentosInicializados.has(seat));

  if (novos.length > 0) {
    const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
    for (const seat of novos) {
      estado.assentosInicializados.add(seat);
    }
    await distribuirCartasParaAssentosOcupados(deckOcorrencia, 5);

    const slotsAtivos = await obterSlotsAtaqueAtivos();
    const nomesAtivos = slotsAtivos.map((s) => s.nomeSnap).join(", ");
    world.broadcast(
      `Novo jogador detectado! Fase 3 agora aguarda ${slotsAtivos.length} jogador(es): ${nomesAtivos}.`
    );
  }
}

async function prepararCartasNosSnapPointsDeAtaque() {
  if (estado.faseAtual !== "FASE_3") return;

  for (const slot of SLOTS_ATAQUE) {
    if (!slot.vinculado) continue;
    const cartas = await cartasNaArea(slot.ponto, RAIO_DETECCAO, RAIO_DETECCAO, true);
    if (cartas.length === 1 && ehCartaDeOcorrencia(cartas[0])) {
      if (cartas[0].faceUp === true && typeof cartas[0].flip === "function") {
        await cartas[0].flip();
        await pausaFisica(0.2);
      }
    }
  }

  const slotsAtivos = await obterSlotsAtaqueAtivos();
  const totalNecessario = slotsAtivos.length;
  if (totalNecessario === 0) return;

  let preenchidos = 0;
  for (const slot of slotsAtivos) {
    if (!slot.vinculado) continue;
    const cartas = await cartasNaArea(slot.ponto, RAIO_DETECCAO, RAIO_DETECCAO, true);
    if (cartas.length === 1 && ehCartaDeOcorrencia(cartas[0])) {
      preenchidos++;
    }
  }

  const statusAtual = `${preenchidos}/${totalNecessario}`;
  if (statusAtual !== estado.ultimoStatusFase3) {
    estado.ultimoStatusFase3 = statusAtual;
    if (preenchidos === totalNecessario) {
      world.broadcast(
        `Snap Points de Ataque: ${preenchidos}/${totalNecessario} Ocorrências prontas! Clique no Deck_Acao (ou em uma das cartas de Ataque) para revelar.`
      );
    } else if (preenchidos > 0) {
      world.broadcast(`Snap Points de Ataque preenchidos: ${preenchidos}/${totalNecessario}.`);
    }
  }
}

async function validarEAvancarParaFase4() {
  if (estado.faseAtual !== "FASE_3") return;

  const slotsAtivos = await obterSlotsAtaqueAtivos();
  if (slotsAtivos.length === 0) {
    world.broadcast("Nenhum jogador está sentado na mesa. Sente-se em um assento antes de revelar.");
    return;
  }

  const indicesAtivos = new Set(slotsAtivos.map((s) => s.indice));
  const selecionadas: { carta: any; slot: SlotAtaque }[] = [];
  const pendentes: string[] = [];

  for (const slot of slotsAtivos) {
    if (!slot.vinculado) {
      pendentes.push(`${slot.nomeSnap} (Snap Point não encontrado na cena)`);
      continue;
    }

    const objetos = await objetosNaArea(slot.ponto, RAIO_DETECCAO, RAIO_DETECCAO, true);
    const total = contarTotalCartas(objetos);

    if (total === 0) {
      pendentes.push(`${slot.nomeSnap} (vazio)`);
      continue;
    }
    if (total > 1) {
      pendentes.push(`${slot.nomeSnap} (>1 carta)`);
      continue;
    }
    if (!ehCartaDeOcorrencia(objetos[0])) {
      pendentes.push(`${slot.nomeSnap} (use uma carta de Ocorrência, não de Ação)`);
      continue;
    }

    selecionadas.push({ carta: objetos[0], slot });
  }

  for (const slot of SLOTS_ATAQUE) {
    if (!slot.vinculado || indicesAtivos.has(slot.indice)) continue;
    const sobras = await objetosNaArea(slot.ponto, RAIO_DETECCAO, RAIO_DETECCAO, false);
    if (sobras.length > 0) {
      pendentes.push(`${slot.nomeSnap} (assento sem jogador — remova a carta)`);
    }
  }

  if (pendentes.length > 0) {
    world.broadcast(`Não foi possível revelar na Fase 3. Verifique: ${pendentes.join(", ")}.`);
    return;
  }

  estado.cartasOcorrenciaEmDisputa.clear();
  for (const { carta, slot } of selecionadas) {
    await moverCartaParaPonto(carta, slot.ponto, true, 0, 0, false);
    if (carta.id) {
      estado.cartasOcorrenciaEmDisputa.add(String(carta.id));
    }
  }

  iniciarFase4();
}

// FASE 4: Jogadores movem as Ocorrências escolhidas de Ataque_X para Ocorrencia_1..3
// e alocam as cartas de Ação nos depósitos Deposito_1A/1B, Deposito_2A/2B, Deposito_3A/3B
function iniciarFase4() {
  estado.faseAtual = "FASE_4";
  atualizarBotaoHud(true, "Concluir Fase 4 -> Fase 5");
  world.broadcast(
    "Fase 4: Ocorrências reveladas! Movam as Ocorrências para Ocorrencia_1, Ocorrencia_2 ou Ocorrencia_3, aloquem as cartas de recurso em Deposito_1A/1B, 2A/2B e 3A/3B e cliquem no Deck_Acao para ir à Fase 5."
  );
}

// FASE 4 -> FASE 5: Valida se cada ocorrência presente em Ocorrencia_1..3 possui cartas em Deposito_XA e Deposito_XB
async function validarEAvancarParaFase5() {
  if (estado.faseAtual !== "FASE_4") return;

  const errosAlocacao: string[] = [];
  let totalOcorrenciasNaMesa = 0;

  for (const slotOc of SLOTS_OCORRENCIA_MESA) {
    if (!slotOc.vinculado) continue;

    const objOcorrencia = await objetosNaArea(slotOc.ponto, RAIO_DETECCAO, RAIO_DETECCAO, false);
    const qtdOcorrencia = contarTotalCartas(objOcorrencia);
    if (qtdOcorrencia === 0) continue;

    totalOcorrenciasNaMesa++;

    const objDepA = slotOc.vinculadoDepositoA
      ? await objetosNaArea(slotOc.pontoDepositoA, RAIO_DETECCAO, RAIO_DETECCAO, false)
      : [];
    const objDepB = slotOc.vinculadoDepositoB
      ? await objetosNaArea(slotOc.pontoDepositoB, RAIO_DETECCAO, RAIO_DETECCAO, false)
      : [];

    const qtdDepA = contarTotalCartas(objDepA);
    const qtdDepB = contarTotalCartas(objDepB);

    if (qtdDepA !== 1 || qtdDepB !== 1) {
      errosAlocacao.push(`Cartas de recurso não foram alocadas na Ocorrência ${slotOc.indice}`);
    }
  }

  if (errosAlocacao.length > 0) {
    for (const msgErro of errosAlocacao) {
      world.broadcast(msgErro);
    }
    return;
  }

  if (totalOcorrenciasNaMesa === 0) {
    world.broadcast("Nenhuma carta encontrada em Ocorrencia_1, Ocorrencia_2 ou Ocorrencia_3.");
    return;
  }

  await executarFase5();
}

