async function obterDadosCustomizadosDaCarta(carta: any): Promise<Record<string, any>> {
  const dadosMesclados: Record<string, any> = {};
  if (!carta || typeof carta !== "object") return dadosMesclados;

  const incorporar = (fonte: any) => {
    if (!fonte || typeof fonte !== "object" || Array.isArray(fonte)) return;
    for (const [k, v] of Object.entries(fonte)) {
      const chaveNorm = String(k).trim().toLowerCase().replace(/\s+/g, "");
      if (chaveNorm && dadosMesclados[chaveNorm] === undefined && v !== undefined && v !== null) dadosMesclados[chaveNorm] = v;
    }
  };

  const metaBase = carta.metadata ?? carta.data?.metadata;
  const defCarta = metaBase?.customDeck?.cards?.find(
    (c: any) => c.cardId === (metaBase?.cardId ?? carta.cardid ?? carta.name) || c.label === carta.name
  );

  if (defCarta?.data) incorporar(defCarta.data);
  else {
    incorporar(carta.data?.data);
    incorporar(carta.data);
    incorporar(carta.cardData);
    incorporar(carta);
  }

  return dadosMesclados;
}

async function extrairAtributosDaCarta(carta: any) {
  const atributos: Record<string, { rotulo: string; valor: number }> = {};
  const paresBrutos: string[] = [];
  if (!carta) return { atributos, paresBrutos };

  const dados = await obterDadosCustomizadosDaCarta(carta);

  for (let i = 1; i <= 3; i++) {
    const rotulo = String(dados[`atributo${i}`] ?? dados[`atributo_${i}`] ?? "").trim();
    if (!rotulo || ["null", "undefined", "nenhum", "-"].includes(rotulo.toLowerCase())) continue;

    const valorNumerico = Number(String(dados[`valor${i}`] ?? dados[`valor_${i}`] ?? "0").trim().replace(",", "."));
    if (Number.isNaN(valorNumerico) || !Number.isFinite(valorNumerico)) continue;

    paresBrutos.push(`${rotulo}=${valorNumerico}`);
    const chaveAtributo = rotulo
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/\s+/g, " ");

    if (!atributos[chaveAtributo]) atributos[chaveAtributo] = { rotulo, valor: 0 };
    atributos[chaveAtributo].valor += valorNumerico;
  }
  return { atributos, paresBrutos };
}

async function calcularPontuacao(cartaOcorrencia: any, cartasAtaque: any[]): Promise<ResultadoPontuacao> {
  const leituraOcorrencia = await extrairAtributosDaCarta(cartaOcorrencia);
  const somaAcao: Record<string, { rotulo: string; valor: number }> = {};

  for (const cartaAcao of cartasAtaque) {
    const leituraAcao = await extrairAtributosDaCarta(cartaAcao);
    for (const [chave, info] of Object.entries(leituraAcao.atributos)) {
      if (!somaAcao[chave]) somaAcao[chave] = { rotulo: info.rotulo, valor: 0 };
      somaAcao[chave].valor += info.valor;
    }
  }

  let totalRequerido = 0,
    totalAtendido = 0;
  for (const [chave, infoOcorrencia] of Object.entries(leituraOcorrencia.atributos)) {
    const requerido = Math.max(0, infoOcorrencia.valor);
    if (requerido <= 0) continue;
    const obtido = Math.max(0, somaAcao[chave]?.valor ?? 0);
    totalRequerido += requerido;
    totalAtendido += Math.min(obtido, requerido);
  }

  if (totalRequerido === 0) return { pontos: 0, percentual: 0, passosDebug: [] };
  const proporcao = Math.min(1, totalAtendido / totalRequerido);
  return {
    pontos: Number((proporcao * 10).toFixed(2)),
    percentual: Number((proporcao * 100).toFixed(2)),
    passosDebug: [],
  };
}

