// FASE 5: Resolve Ocorrencia_1, 2 e 3 -> OcorrenciasResolvidas; envia sobras -> OcorrenciasFail; prepara próximo turno
async function executarFase5() {
  estado.faseAtual = "FASE_5";
  atualizarBotaoHud(false);
  estado.pareamentosRodada = [];

  const pontoResolvidas = POSICOES_MESA.OcorrenciasResolvidas;
  const pontoFail = POSICOES_MESA.OcorrenciasFail;

  let indicePilhaResolvidas = contarTotalCartas(
    await objetosNaArea(pontoResolvidas, RAIO_DETECCAO, RAIO_DETECCAO, false)
  );
  let indicePilhaFail = contarTotalCartas(
    await objetosNaArea(pontoFail, RAIO_DETECCAO, RAIO_DETECCAO, false)
  );

  let pontosGanhosNaRodada = 0;
  const detalhesResolucao: string[] = [];

  // --------------------------------------------------------------------------
  // PASSOS 1, 2 e 3: Ocorrencia_1, Ocorrencia_2 e Ocorrencia_3
