async function objetosNaArea(centro, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false) {
    const todos = await listarTodosObjetos();
    return todos.filter((obj) => {
        if (!obj || obj.name === "Deck_Ocorrencia" || obj.name === "Deck_Acao")
            return false;
        const kind = String(obj.kind ?? "").toLowerCase();
        if (kind !== "card" && kind !== "deck")
            return false;
        return dentroDaArea(obj.position, centro, raioX, raioZ) && (!apenasAssentadas || estaCartaAssentada(obj, centro));
    });
}
async function cartasNaArea(centro, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO, apenasAssentadas = false) {
    const objetos = await objetosNaArea(centro, raioX, raioZ, apenasAssentadas);
    return objetos.filter((obj) => (obj.stackCount ?? 1) <= 1);
}
function contarTotalCartas(objetos) {
    return objetos.reduce((soma, obj) => soma + Number(obj?.stackCount ?? 1), 0);
}
async function definirTravaFisica(obj, travar) {
    if (!obj)
        return;
    try {
        if (travar && typeof obj.lock === "function")
            await obj.lock();
        else if (!travar && typeof obj.unlock === "function")
            await obj.unlock();
        else if ("locked" in obj)
            obj.locked = travar;
    }
    catch (_) { }
}
async function moverCartaParaPonto(carta, destino, viradaParaCima, rotacaoY = 0, indicePilha = 0, travarNaMesa = false) {
    if (!carta || !destino)
        return;
    await definirTravaFisica(carta, false);
    if (viradaParaCima && carta.faceUp === false && typeof carta.flip === "function") {
        await carta.flip();
        await pausaFisica(0.22);
    }
    else if (!viradaParaCima && carta.faceUp === true && typeof carta.flip === "function") {
        await carta.flip();
        await pausaFisica(0.22);
    }
    if (typeof carta.setRotation === "function") {
        const rotAtual = Array.isArray(carta.rotation) ? carta.rotation : [0, rotacaoY, 0];
        const virouPeloEixoX = Math.abs(Number(rotAtual[0] ?? 0)) > 90;
        const rzNormalizado = virouPeloEixoX ? (Math.abs(Number(rotAtual[2] ?? 0)) > 90 ? 0 : 180) : Number(rotAtual[2] ?? 0);
        await carta.setRotation([0, rotacaoY, rzNormalizado]);
    }
    const ySeguro = Number((Math.max(destino[1], ALTURA_MESA) + indicePilha * 0.015).toFixed(3));
    if (typeof carta.setPosition === "function")
        await carta.setPosition([destino[0], ySeguro, destino[2]]);
    await definirTravaFisica(carta, travarNaMesa);
    if (typeof carta.refresh === "function")
        await carta.refresh();
    await pausaFisica(0.06);
}
async function puxarCartaDoDeck(deck) {
    if (!deck || (deck.stackCount ?? 0) <= 0)
        return null;
    let carta = typeof deck.drawCard === "function" ? await deck.drawCard() : typeof deck.draw === "function" ? await deck.draw(1) : null;
    if (Array.isArray(carta))
        carta = carta[0];
    return carta ?? null;
}
async function descompactarPilhas(objetos) {
    const individuais = [];
    for (const obj of objetos) {
        if (!obj)
            continue;
        await definirTravaFisica(obj, false);
        while ((obj.stackCount ?? 1) > 1) {
            const extra = await puxarCartaDoDeck(obj);
            if (!extra)
                break;
            individuais.push(extra);
        }
        individuais.push(obj);
    }
    return individuais;
}
function extrairIdentificadorPlayer(p, fallbackIdx) {
    if (!p || typeof p !== "object")
        return "";
    if (p.isSpectator === true)
        return "";
    const papel = String(p.role ?? p.type ?? "").trim().toLowerCase();
    if (papel === "spectator")
        return "";
    const candidatos = [
        p.seat,
        p.seatId,
        p.seatColor,
        p.color,
        p.handSeat,
        p.seatName,
        p.assignedSeat,
        typeof p.seatIndex === "number" ? `seat_${p.seatIndex + 1}` : "",
    ];
    for (const c of candidatos) {
        const val = String(c ?? "").trim().toLowerCase();
        if (!val || val === "null" || val === "undefined")
            continue;
        if (val === "spectator" || val === "none")
            return "";
        return val;
    }
    const idJogador = String(p.id ?? p.playerId ?? p.userId ?? p.__chaveSeat ?? "").trim().toLowerCase();
    return idJogador || `player_${fallbackIdx + 1}`;
}
async function obterAssentosOcupados() {
    const w = world;
    const playersBruto = typeof w.getPlayers === "function" ? await w.getPlayers() : [];
    const listaPlayers = normalizarColecao(playersBruto);
    const assentos = [];
    for (let i = 0; i < listaPlayers.length; i++) {
        const idAssento = extrairIdentificadorPlayer(listaPlayers[i], i);
        if (idAssento && !assentos.includes(idAssento)) {
            assentos.push(idAssento);
        }
    }
    const seatZonesBruto = typeof w.getSeatZones === "function" ? await w.getSeatZones() : [];
    const listaZonas = normalizarColecao(seatZonesBruto);
    for (const z of listaZonas) {
        if (!z || typeof z !== "object")
            continue;
        const ocupado = Boolean(z.occupied || z.playerId || z.occupiedBy || z.occupantId || z.player);
        if (!ocupado)
            continue;
        const seat = String(z.seat ?? z.seatId ?? z.__chaveSeat ?? "").trim().toLowerCase();
        if (seat && seat !== "spectator" && seat !== "none" && !assentos.includes(seat)) {
            assentos.push(seat);
        }
    }
    return assentos.slice(0, MAX_JOGADORES);
}
async function obterSlotsAtaqueAtivos() {
    const assentosAtuais = await obterAssentosOcupados();
    const todosAssentosDaRodada = [...assentosAtuais];
    for (const seat of estado.assentosInicializados) {
        if (!todosAssentosDaRodada.includes(seat)) {
            todosAssentosDaRodada.push(seat);
        }
    }
    const indicesUsados = new Set();
    const slotsAtivos = [];
    for (let i = 0; i < todosAssentosDaRodada.length; i++) {
        const seat = todosAssentosDaRodada[i];
        let indice = estado.mapaAssentoParaIndice.get(seat) ?? extrairIndiceAssento(seat, "", i + 1);
        if (indicesUsados.has(indice)) {
            const livre = SLOTS_ATAQUE.find((s) => !indicesUsados.has(s.indice));
            if (livre)
                indice = livre.indice;
        }
        indicesUsados.add(indice);
        const slot = SLOTS_ATAQUE[indice - 1];
        if (slot)
            slotsAtivos.push(slot);
    }
    return slotsAtivos.sort((a, b) => a.indice - b.indice);
}
async function virarParaCimaCartasNasMaos() {
    const todos = await listarTodosObjetos();
    for (const obj of todos) {
        if (!obj || obj.name === "Deck_Ocorrencia" || obj.name === "Deck_Acao")
            continue;
        const kind = String(obj.kind ?? "").toLowerCase();
        if (kind !== "card")
            continue;
        if (estaEmAlgumSnapPointDaMesa(obj.position))
            continue;
        if (obj.faceUp === false && typeof obj.flip === "function") {
            try {
                await obj.flip();
                if (typeof obj.refresh === "function")
                    await obj.refresh();
                await pausaFisica(0.05);
            }
            catch (_) { }
        }
    }
}
async function contarCartasNasMaos() {
    const todos = await listarTodosObjetos();
    let total = 0;
    for (const obj of todos) {
        if (!obj || obj.name === "Deck_Ocorrencia" || obj.name === "Deck_Acao")
            continue;
        const kind = String(obj.kind ?? "").toLowerCase();
        if (kind !== "card" && kind !== "deck")
            continue;
        if (estaEmAlgumSnapPointDaMesa(obj.position))
            continue;
        total += Number(obj.stackCount ?? 1);
    }
    return total;
}
async function distribuirCartasParaAssentosOcupados(deck, quantidadePorJogador) {
    if (!deck || typeof deck.deal !== "function")
        return;
    for (let i = 0; i < quantidadePorJogador; i++) {
        if ((deck.stackCount ?? 0) <= 0)
            break;
        try {
            await deck.deal();
            if (typeof deck.refresh === "function") {
                await deck.refresh();
            }
            await pausaFisica(0.28);
        }
        catch (_) { }
    }
    await virarParaCimaCartasNasMaos();
}
