// FASE 5: Resolve Ocorrencia_1, 2 e 3 -> OcorrenciasResolvidas; envia sobras -> OcorrenciasFail; prepara próximo turno
async function executarFase5() {
    estado.faseAtual = "FASE_5";
    atualizarBotaoHud(false);
    estado.pareamentosRodada = [];
    const pontoResolvidas = POSICOES_MESA.OcorrenciasResolvidas;
    const pontoFail = POSICOES_MESA.OcorrenciasFail;
    let indicePilhaResolvidas = contarTotalCartas(await objetosNaArea(pontoResolvidas, RAIO_DETECCAO, RAIO_DETECCAO, false));
    let indicePilhaFail = contarTotalCartas(await objetosNaArea(pontoFail, RAIO_DETECCAO, RAIO_DETECCAO, false));
    let pontosGanhosNaRodada = 0;
    const detalhesResolucao = [];
    // --------------------------------------------------------------------------
    // PASSOS 1, 2 e 3: Ocorrencia_1, Ocorrencia_2 e Ocorrencia_3
    // --------------------------------------------------------------------------
    for (const slotOc of SLOTS_OCORRENCIA_MESA) {
        if (!slotOc.vinculado)
            continue;
        const objOcorrencia = await objetosNaArea(slotOc.ponto, RAIO_DETECCAO, RAIO_DETECCAO, false);
        if (objOcorrencia.length === 0)
            continue;
        const objDepA = slotOc.vinculadoDepositoA
            ? await objetosNaArea(slotOc.pontoDepositoA, RAIO_DETECCAO, RAIO_DETECCAO, false)
            : [];
        if (objDepA.length === 0)
            continue;
        const objDepB = slotOc.vinculadoDepositoB
            ? await objetosNaArea(slotOc.pontoDepositoB, RAIO_DETECCAO, RAIO_DETECCAO, false)
            : [];
        if (objDepB.length === 0)
            continue;
        const cartasOcorrencia = await descompactarPilhas(objOcorrencia);
        const cartasDepositoA = await descompactarPilhas(objDepA);
        const cartasDepositoB = await descompactarPilhas(objDepB);
        const cartaOcorrencia = cartasOcorrencia[0];
        const cartasRecursos = [cartasDepositoA[0], cartasDepositoB[0]];
        // Calcula os pontos usando essas 3 cartas (Ocorrência + Deposito_XA + Deposito_XB)
        const resultado = await calcularPontuacao(cartaOcorrencia, cartasRecursos);
        estado.pontuacaoOculta = Number((estado.pontuacaoOculta + resultado.pontos).toFixed(2));
        pontosGanhosNaRodada = Number((pontosGanhosNaRodada + resultado.pontos).toFixed(2));
        estado.pareamentosRodada.push({
            indice: slotOc.indice,
            nomeOcorrencia: slotOc.nomeSnap,
            cartaOcorrencia,
            cartasDepositoA,
            cartasDepositoB,
            todasCartasAcao: cartasRecursos,
        });
        detalhesResolucao.push(`Ocorrência ${slotOc.indice} ("${cartaOcorrencia?.name ?? "Carta"}"): +${resultado.pontos} pts (${resultado.percentual}%)`);
        // Move as 3 cartas para o Snap Point OcorrenciasResolvidas
        const cartasParaResolver = [...cartasOcorrencia, ...cartasDepositoA, ...cartasDepositoB];
        for (const carta of cartasParaResolver) {
            await moverCartaParaPonto(carta, pontoResolvidas, true, 0, indicePilhaResolvidas++, true);
        }
    }
    // --------------------------------------------------------------------------
    // PASSO 4: Sobras em Ataque_1..10, Acao_1..7 e Zona_Descarte -> OcorrenciasFail
    // --------------------------------------------------------------------------
    const pontosParaLimpar = [];
    for (const slotAt of SLOTS_ATAQUE) {
        if (slotAt.vinculado) {
            pontosParaLimpar.push({ nome: slotAt.nomeSnap, centro: slotAt.ponto });
        }
    }
    for (let i = 1; i <= 7; i++) {
        pontosParaLimpar.push({ nome: `Acao_${i}`, centro: POSICOES_MESA[`Acao_${i}`] });
    }
    pontosParaLimpar.push({ nome: "Zona_Descarte", centro: POSICOES_MESA.Zona_Descarte });
    let totalEnviadasParaFail = 0;
    for (const alvo of pontosParaLimpar) {
        const sobras = await objetosNaArea(alvo.centro, RAIO_DETECCAO, RAIO_DETECCAO, false);
        if (sobras.length === 0)
            continue;
        const cartasIndividuais = await descompactarPilhas(sobras);
        for (const carta of cartasIndividuais) {
            await moverCartaParaPonto(carta, pontoFail, true, 0, indicePilhaFail++, true);
            const perda = await calcularFracasso(carta, alvo.nome);
            estado.pontuacaoFracasso = Number((estado.pontuacaoFracasso + perda).toFixed(2));
            totalEnviadasParaFail++;
        }
    }
    world.broadcast(`Rodada ${estado.rodada} concluída! ${detalhesResolucao.join(" | ") || "Nenhuma ocorrência resolvida."} | Sobras enviadas para OcorrenciasFail: ${totalEnviadasParaFail} carta(s) | Placar acumulado: ${estado.pontuacaoOculta} pts.`);
    // --------------------------------------------------------------------------
    // SETUP PARA O PRÓXIMO TURNO (OU FIM DE JOGO)
    // --------------------------------------------------------------------------
    await pausaFisica(0.8);
    const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
    const deckAcao = await obterObjetoPorNome("Deck_Acao");
    const restantesDeckOcorrencia = Number(deckOcorrencia?.stackCount ?? 0);
    const restantesDeckAcao = Number(deckAcao?.stackCount ?? 0);
    const cartasNasMaos = await contarCartasNasMaos();
    const semAcoesParaNovoTurno = restantesDeckAcao <= 0;
    const semOcorrenciasNoJogo = restantesDeckOcorrencia <= 0 && cartasNasMaos <= 0;
    if (semAcoesParaNovoTurno || semOcorrenciasNoJogo) {
        estado.faseAtual = "FIM_DE_JOGO";
        world.broadcast(`Fim de Jogo! Pontuação Final: ${estado.pontuacaoOculta} pts (Total de rodadas: ${estado.rodada}).`);
        return;
    }
    estado.rodada++;
    await executarFase1();
}
