async function iniciarMonitoramentoContinuo() {
    const todosIniciais = await listarTodosObjetos();
    atualizarHistoricoPosicoes(todosIniciais);
    while (estado.faseAtual !== "FIM_DE_JOGO") {
        const pausou = await pausaFisica(0.4);
        if (!pausou)
            break;
        if (estado.ocupado)
            continue;
        estado.ocupado = true;
        try {
            const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
            const deckAcao = await obterObjetoPorNome("Deck_Acao");
            if (estado.faseAtual === "FASE_3") {
                await verificarNovosAssentosOcupados();
                await prepararCartasNosSnapPointsDeAtaque();
                // Atalho reserva: apertar F sobre Deck_Ocorrencia ou Deck_Acao revela as Ocorrências
                if (deckOcorrencia && Boolean(deckOcorrencia.faceUp) !== estado.deckOcorrenciaFaceUpBase) {
                    if (typeof deckOcorrencia.flip === "function") {
                        await deckOcorrencia.flip();
                        await pausaFisica(0.25);
                    }
                    estado.deckOcorrenciaFaceUpBase = Boolean(deckOcorrencia.faceUp);
                    await validarEAvancarParaFase4();
                }
                else if (deckAcao && Boolean(deckAcao.faceUp) !== estado.deckAcaoFaceUpBase) {
                    if (typeof deckAcao.flip === "function") {
                        await deckAcao.flip();
                        await pausaFisica(0.25);
                    }
                    estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);
                    await validarEAvancarParaFase4();
                }
            }
            else if (estado.faseAtual === "FASE_4") {
                // Atalho reserva: apertar F sobre Deck_Acao conclui a Fase 4
                if (deckAcao && Boolean(deckAcao.faceUp) !== estado.deckAcaoFaceUpBase) {
                    if (typeof deckAcao.flip === "function") {
                        await deckAcao.flip();
                        await pausaFisica(0.25);
                    }
                    estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);
                    await validarEAvancarParaFase5();
                }
            }
            atualizarHistoricoPosicoes(await listarTodosObjetos());
        }
        finally {
            estado.ocupado = false;
        }
    }
}
